#[test]
fn strip_ansi_matches_strip_ansi_7() {
    assert_eq!(strip_ansi("\u{1b}[31mred\u{1b}[0m"), "red");
    assert_eq!(strip_ansi("a\u{1b}]0;title\u{7}b"), "ab");
    assert_eq!(
        strip_ansi("a\u{1b}]8;;http://x\u{1b}\\link\u{1b}]8;;\u{1b}\\"),
        "alink"
    );
    assert_eq!(strip_ansi("\u{9b}1;2Htext"), "text");
    assert_eq!(strip_ansi("plain"), "plain");
}

#[test]
fn trim_end_follows_js_whitespace() {
    assert_eq!(trim_end_js("a \t\u{a0}\u{feff}"), "a");
    assert_eq!(trim_end_js("a\u{85}"), "a\u{85}");
}

#[test]
fn title_reports_latest_nonempty_osc_title() {
    let mut emulator = Emulator::new(4, 10, 100);
    assert_eq!(emulator.title(), None);
    emulator.feed(b"\x1b]0;hello\x07");
    assert_eq!(emulator.title().as_deref(), Some("hello"));
    emulator.feed(b"\x1b]2;   \x07");
    assert_eq!(emulator.title(), None);
}

fn grid_text(emulator: &Emulator) -> Vec<String> {
    let state = emulator.snapshot(&SnapshotOptions::default());
    state["grid"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            row.as_array()
                .unwrap()
                .iter()
                .map(|c| c["char"].as_str().unwrap())
                .collect()
        })
        .collect()
}

#[test]
fn utf8_split_across_feeds_matches_single_feed() {
    let text = "日本語 é 😀 ok\r\nnext";
    let bytes = text.as_bytes();
    let mut whole = Emulator::new(3, 20, 10);
    whole.feed(bytes);
    for cut in 1..bytes.len() {
        let mut split = Emulator::new(3, 20, 10);
        split.feed(&bytes[..cut]);
        split.feed(&bytes[cut..]);
        assert_eq!(grid_text(&split), grid_text(&whole), "cut at {cut}");
    }
}

#[test]
fn invalid_utf8_becomes_replacement_char() {
    let mut emulator = Emulator::new(2, 6, 0);
    emulator.feed(&[b'a', 0xff, b'b']);
    assert_eq!(grid_text(&emulator)[0], "a\u{fffd}b   ");
}

#[test]
fn cursor_position_follows_output() {
    let mut emulator = Emulator::new(5, 10, 0);
    emulator.feed(b"ab\r\ncd");
    assert_eq!(emulator.cursor_position(), (1, 2));
}

#[test]
fn degenerate_sizes_are_clamped() {
    let mut emulator = Emulator::new(0, 0, 5);
    emulator.feed(b"hello\r\nworld");
    emulator.resize(0, 1);
    emulator.feed(b"\x1b[2J\x1b[3J");
    let state = emulator.snapshot(&SnapshotOptions::default());
    assert!(state["rows"].as_u64().unwrap() >= 1 && state["cols"].as_u64().unwrap() >= 2);
}

/// Deterministic byte soup plus resizes must never panic (xterm.js tolerates anything).
#[test]
fn random_input_and_resizes_do_not_panic() {
    let mut seed = 0x9e37_79b9_7f4a_7c15_u64;
    let mut next = move || {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        seed
    };
    let alphabet: &[&str] = &[
        "\x1b[", "\x1b]0;", "\x1bP", "\x1b", ";", ":", "?", "1", "2", "38;5;", "m", "H", "J", "K",
        "L", "M", "@", "P", "X", "r", "h", "l", "A", "B", "C", "D", "\r\n", "\n", "\t", "\x08",
        "\x07", "\x1bM", "\x1b7", "\x1b8", "日", "😀", "e\u{301}", "\u{200d}", "abc", " ", "\x18",
        "\x1a", "\x1b\\", "?1049h", "?1049l",
    ];
    for round in 0..300 {
        let rows = 1 + (next() % 8) as u16;
        let cols = 2 + (next() % 14) as u16;
        let mut emulator = Emulator::new(rows, cols, [0usize, 5, 1000][(next() % 3) as usize]);
        for _ in 0..(5 + next() % 20) {
            let mut chunk = String::new();
            for _ in 0..(1 + next() % 12) {
                chunk.push_str(alphabet[(next() % alphabet.len() as u64) as usize]);
            }
            emulator.feed(chunk.as_bytes());
            if next() % 4 == 0 {
                emulator.resize(1 + (next() % 9) as u16, 1 + (next() % 16) as u16);
            }
            let opts = SnapshotOptions {
                scrollback_lines: None,
                include_wrap_flags: Some(true),
            };
            let state = emulator.snapshot(&opts);
            assert!(state["grid"].as_array().is_some(), "round {round}");
        }
        let _ = emulator.capture(Some(-3), None, true);
    }
}
